"""Apply the existing SAM writer grant list only. Never changes code, env, data or gates."""
import argparse, hashlib, json, pathlib, subprocess
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=pathlib.Path('/private/tmp/finance58');STACK='staging-finance-commercial-writer-access-58'
def digest(v):return hashlib.sha256(json.dumps(v,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def main(mode):
 import boto3
 s=boto3.Session(profile_name='Wizz_stg_UserApp',region_name='us-east-1');assert s.client('sts').get_caller_identity()['Account']=='699561669180'
 cf=s.client('cloudformation');iam=s.client('iam');lam=s.client('lambda');base=json.loads((OUT/'writer.config.private.json').read_text());template=json.loads((ROOT/'backend/finance-commercial-writer-access.staging.json').read_text());assert set(template['Resources'])=={'CommercialWriterAccess'}
 p=json.loads(subprocess.check_output(['node','scripts/prepare-commercial-writer-access.cjs'],cwd=ROOT));resource=template['Resources']['CommercialWriterAccess'];assert resource['Type']=='AWS::IAM::Policy' and resource['Condition']=='StagingAccountAndRegion';props=resource['Properties'];assert props['PolicyDocument']==p['document'] and props['Roles']==[base['Role'].rsplit('/',1)[1]]
 def stable():
  live=lam.get_function_configuration(FunctionName=base['FunctionName']);assert live['CodeSha256']==base['CodeSha256'] and live['RevisionId']==base['RevisionId']
  assert live['Environment']==base['Environment'] and live['Role']==base['Role'];env=live['Environment']['Variables'];assert env.get('COMMERCIAL_PRICING_MODE','OFF')=='OFF' and env.get('DELIVERY_QUOTE_MODE','OFF')=='OFF' and not env.get('FINANCE_ROLLOUT_CONFIG');return live
 stable()
 # Test the reviewed statement set, and (after application) the effective existing role.
 checks=[('dynamodb:GetItem','staging-MerchantPlatform','COMMERCIAL_AGREEMENT#synthetic58','allowed'),('dynamodb:ConditionCheckItem','staging-MerchantPlatform','COMMERCIAL_AGREEMENT#synthetic58','allowed'),('dynamodb:GetItem','staging-PlatformStaff','DISCOUNT_FUNDING#synthetic58','allowed'),('dynamodb:ConditionCheckItem','staging-PlatformStaff','DISCOUNT_FUNDING#synthetic58','allowed'),('dynamodb:UpdateItem','staging-Wallets','WALLET#PLATFORM','allowed'),('dynamodb:PutItem','staging-Holds','synthetic58','allowed'),('dynamodb:PutItem','staging-LedgerEntries','WALLET#PLATFORM','allowed'),('dynamodb:PutItem','staging-AuditLog','PROMO#synthetic58','allowed'),('dynamodb:UpdateItem','staging-DeliveryQuotes','CUSTOMER#synthetic58','allowed'),('dynamodb:UpdateItem','staging-Wallets','WALLET#DRIVER#synthetic58','implicitDeny'),('dynamodb:PutItem','staging-LedgerEntries','WALLET#DRIVER#synthetic58','implicitDeny'),('dynamodb:DeleteItem','staging-Holds','synthetic58','implicitDeny'),('dynamodb:PutItem','staging-MerchantPlatform','COMMERCIAL_AGREEMENT#synthetic58','implicitDeny'),('dynamodb:PutItem','staging-PlatformStaff','DISCOUNT_FUNDING#synthetic58','implicitDeny'),('dynamodb:PutItem','staging-DeliveryQuotes','CUSTOMER#synthetic58','implicitDeny')]
 rows=[]
 for action,table,key,expected in checks:
  kwargs={'ActionNames':[action],'ResourceArns':['arn:aws:dynamodb:us-east-1:699561669180:table/'+table],'ContextEntries':[{'ContextKeyName':'dynamodb:LeadingKeys','ContextKeyType':'stringList','ContextKeyValues':[key]}]}
  decision=(iam.simulate_custom_policy(PolicyInputList=[json.dumps(p['document'])],**kwargs) if mode in ['review','apply'] else iam.simulate_principal_policy(PolicySourceArn=base['Role'],**kwargs))['EvaluationResults'][0]['EvalDecision'];assert decision==expected,(action,table,decision);rows.append({'action':action,'table':table,'keyClass':'platform' if key=='WALLET#PLATFORM' else 'foreign' if expected=='implicitDeny' else 'synthetic','decision':decision})
 if mode=='review':
  change=cf.create_change_set(StackName=STACK,ChangeSetName='commercial58-existing-sam-writer-grants',ChangeSetType='CREATE',TemplateBody=json.dumps(template),Capabilities=['CAPABILITY_NAMED_IAM']);(OUT/'writer-changeset.json').write_text(json.dumps({'changeSetArn':change['Id'],'templateDigest':digest(template),'sourceTemplateSha256':p['sourceSha256'],'customPolicySimulation':rows},indent=2));print(json.dumps({'changeSetCreated':True,'policiesApplied':False,'gatesChanged':False}));return
 state=json.loads((OUT/'writer-changeset.json').read_text());assert state['templateDigest']==digest(template) and state['sourceTemplateSha256']==p['sourceSha256'];change=cf.describe_change_set(ChangeSetName=state['changeSetArn']);changes=change.get('Changes',[]);assert change['Status']=='CREATE_COMPLETE' and len(changes)==1;row=changes[0]['ResourceChange'];assert row['Action']=='Add' and row['ResourceType']=='AWS::IAM::Policy' and row['LogicalResourceId']=='CommercialWriterAccess'
 if mode=='apply':
  assert change['ExecutionStatus']=='AVAILABLE';cf.execute_change_set(ChangeSetName=state['changeSetArn']);cf.get_waiter('stack_create_complete').wait(StackName=STACK,WaiterConfig={'Delay':3,'MaxAttempts':90});print(json.dumps({'writerPolicyApplied':True,'verifyEffectiveAccessNext':True,'gatesChanged':False}));return
 assert cf.describe_stacks(StackName=STACK)['Stacks'][0]['StackStatus']=='CREATE_COMPLETE';assert iam.get_role_policy(RoleName=props['Roles'][0],PolicyName=props['PolicyName'])['PolicyDocument']==p['document'];live=stable()
 report={'part':58,'environment':'Staging','stackName':STACK,'writer':{'name':live['FunctionName'],'role':live['Role'],'codeSha256':live['CodeSha256'],'revisionId':live['RevisionId'],'environmentPreserved':True},'effectiveAccess':rows,'sourceTemplateSha256':p['sourceSha256'],'activationPerformed':False};(OUT/'writer-access-verification.json').write_text(json.dumps(report,indent=2));print(json.dumps({'effectiveChecks':len(rows),'codeChanged':False,'gatesChanged':False}))
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('mode',choices=['review','apply','verify']);main(a.parse_args().mode)
